"""How many objects a subject stands for, against how many its reader can grade (T2.2, T2.5).

The form contract closed one half of this: `SHAPES` says a `subject:` parameter is the name of
a declared subject, and the lint reads it. What no one compared was the *arity of the
referent*. `the_aschenblums: {surname: Aschenblum, count: 7}` is a perfectly well-formed
subject name — a non-empty string — handed to a kind that resolves it through
`Evidence.ids()`, which refuses anything but one.

It cost a full sweep to find out. uc21 failed 3 of 3 runs with `subject 'the_aschenblums'
names 7 objects where one is meant`, and because that arrives as a `ProbeError` like any
failed assertion, the sweep wrote an issue draft accusing the product. The model had done the
work; the grader could not read its own catalog.

So arity is declared, like form: a kind says per parameter whether it grades one object or all
of them, the lint compares that against what the subject names, and `ONE_SUBJECT` /
`MANY_SUBJECTS` are derived from that same registry rather than kept beside it — a second list
is how the first one falls behind.
"""

from __future__ import annotations

from typing import Any

from fixtures import stage2_records as make
from stage2 import assertion_kinds, grading, validate
from stage2.catalog import Assertion, UseCase, load_all

BEFORE = make.state(
    people=(
        make.person("I0000", "Bertram", "Aschenblum", gender=make.MALE),
        make.person("I0001", "Cordula", "Aschenblum"),
        make.person("I0002", "Elvide", "Aschenblum"),
        make.person("I0003", "Rosalind", "Steinbrecht"),
    ),
)

ALL_THREE = make.state(
    people=(
        make.person("I0000", "Bertram", "Aschenbluhm", gender=make.MALE),
        make.person("I0001", "Cordula", "Aschenbluhm"),
        make.person("I0002", "Elvide", "Aschenbluhm"),
        make.person("I0003", "Rosalind", "Steinbrecht"),
    ),
)

ONE_MISSED = make.state(
    people=(
        make.person("I0000", "Bertram", "Aschenbluhm", gender=make.MALE),
        make.person("I0001", "Cordula", "Aschenblum"),  # the one the model forgot
        make.person("I0002", "Elvide", "Aschenbluhm"),
        make.person("I0003", "Rosalind", "Steinbrecht"),
    ),
)


def use_case(*assertions: Assertion) -> UseCase:
    return UseCase(
        id="uc0",
        slug="uc00-probe",
        tier=1,
        prompt="p",
        primary=("gramps_set_surname_bulk",),
        decoys=(),
        secondary=(),
        subjects={
            "the_lot": {"namespace": "people", "surname": "Aschenblum", "count": 3},
            "one_of_them": {
                "namespace": "people",
                "first_name": "Rosalind",
                "surname": "Steinbrecht",
            },
        },
        guards={"people": [], "families": [], "sources": []},
        maxdrop=0,
        assertions=assertions,
        waivers=(),
        path=make.__file__,  # type: ignore[arg-type]
    )


def graded(assertion: Assertion, after: Any) -> grading.Outcome:
    case = use_case(assertion)
    return grading.grade(case, grading.evidence_for(case, BEFORE, after))[0]


def test_the_catalog_never_hands_a_set_to_a_kind_that_grades_one() -> None:
    """The live net. uc21 is why it exists, and the whole catalog answers to it."""
    found = [problem for case in load_all().values() for problem in validate.subject_arity(case)]

    assert found == []


def test_a_kind_that_grades_one_object_refuses_a_counted_subject() -> None:
    """`alternates` reads a single record: which of the three would it be counting?"""
    problems = validate.subject_arity(
        use_case(Assertion("a", "alternates", {"subject": "the_lot", "count": 1}))
    )

    assert len(problems) == 1
    assert "the_lot" in problems[0] and "3" in problems[0]


def test_a_kind_that_grades_every_object_it_is_given_accepts_one() -> None:
    """The other half: declaring the arity has to *permit* the legitimate case, or uc21 is
    merely refused instead of graded."""
    assert (
        validate.subject_arity(
            use_case(Assertion("a", "person", {"subject": "the_lot", "fields": {"surname": "x"}}))
        )
        == []
    )


def test_a_named_subject_is_still_one_object_for_the_kinds_that_read_one() -> None:
    assert (
        validate.subject_arity(
            use_case(Assertion("a", "alternates", {"subject": "one_of_them", "count": 1}))
        )
        == []
    )


def test_every_object_a_counted_subject_names_has_to_satisfy_the_fields() -> None:
    outcome = graded(
        Assertion("a", "person", {"subject": "the_lot", "fields": {"surname": "Aschenbluhm"}}),
        ALL_THREE,
    )

    assert outcome.passed, outcome.detail


def test_the_one_the_model_forgot_is_named_in_the_failure() -> None:
    """ "Seven of them" is the whole point of uc21: grading one and stopping would pass a call
    that renamed a single person and left six behind."""
    outcome = graded(
        Assertion("a", "person", {"subject": "the_lot", "fields": {"surname": "Aschenbluhm"}}),
        ONE_MISSED,
    )

    assert not outcome.passed
    assert "I0001" in outcome.detail


def test_the_subject_parameter_sets_are_derived_from_the_shape_registry() -> None:
    """Held so a hand-kept copy cannot *drift* from the registry.

    `ONE_SUBJECT`/`MANY_SUBJECTS` used to be written out beside `shapes=`, which is the same
    second-enumeration defect the Dockerfile's `COPY` list has shipped twice: a kind grows a
    subject parameter, the copy does not, and the new parameter is silently outside the lint.

    What this does not catch, stated rather than implied: a hand-written set whose values are
    correct *today* passes, because both sides are read from the same registry. It goes red on
    the next kind that grows a subject parameter — which is the failure mode, not the shape of
    the source line.
    """
    assert assertion_kinds.ONE_SUBJECT == frozenset(
        parameter
        for kind in assertion_kinds.KINDS.values()
        for parameter, shape in kind.shapes.items()
        if shape in assertion_kinds.NAMES_ONE_SUBJECT
    )
    assert assertion_kinds.MANY_SUBJECTS == frozenset(
        parameter
        for kind in assertion_kinds.KINDS.values()
        for parameter, shape in kind.shapes.items()
        if shape in assertion_kinds.NAMES_SEVERAL_SUBJECTS
    )
